# Decode a scenario label such as "SSP2-4.5"
stories = {1: "Sustainability", 2: "Middle of the road", 3: "Regional rivalry",
           4: "Inequality", 5: "Fossil-fuelled development"}

def decode(label):
    ssp, forcing = label.replace("SSP", "").split("-")
    return f"{label}: society = {stories[int(ssp)]}; extra heat-trapping in 2100 = {forcing} W/m2"

for lab in ("SSP1-1.9", "SSP2-4.5", "SSP5-8.5"):
    print(decode(lab))
